"""PKT1 -- a tiny custom binary container format.

Spec
----
A PKT1 file is a header followed by zero or more records.

Header (8 bytes):
    offset 0: 4 bytes  magic, exactly b'PKT1'
    offset 4: 1 byte   version, must be 1
    offset 5: 2 bytes  record count, u16, little-endian

Record:
    u16 LE id            (arbitrary 16-bit identifier)
    u8  type tag         1 = utf-8 string
                         2 = unsigned 32-bit integer (payload exactly 4 bytes)
                         3 = raw bytes
    u16 LE payload length
    payload              <payload length> bytes

All multi-byte integers are little-endian.

Errors (all subclasses of PktError):
    BadMagic             first four bytes are not b'PKT1'
    UnsupportedVersion   version byte is not 1
    TruncatedFile        file ends mid-record / mid-payload / before the
                         number of records promised by the header; the
                         exception message names the offending record index
    FormatError          structural violation inside a valid-length payload,
                         e.g. a type-tag-2 payload that is not exactly 4 bytes
"""

from __future__ import annotations

import struct

MAGIC = b"PKT1"
VERSION = 1

HEADER = struct.Struct("<4sBH")
RECORD_HEAD = struct.Struct("<HBH")  # id, tag, payload length

TAG_STRING = 1
TAG_U32 = 2
TAG_BYTES = 3


class PktError(Exception):
    """Base class for all PKT1 errors."""


class BadMagic(PktError):
    pass


class UnsupportedVersion(PktError):
    pass


class TruncatedFile(PktError):
    pass


class FormatError(PktError):
    pass


def _encode_payload(tag: int, value) -> bytes:
    if tag == TAG_STRING:
        return value.encode("utf-8")
    if tag == TAG_U32:
        return struct.pack("<I", value)
    if tag == TAG_BYTES:
        return bytes(value)
    raise FormatError(f"unknown type tag {tag}")


def _decode_payload(tag: int, payload: bytes):
    if tag == TAG_STRING:
        try:
            return payload.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise FormatError(f"invalid utf-8 string payload: {exc}") from exc
    if tag == TAG_U32:
        if len(payload) != 4:
            raise FormatError(
                f"u32 payload must be exactly 4 bytes, got {len(payload)}"
            )
        return struct.unpack("<I", payload)[0]
    if tag == TAG_BYTES:
        return payload
    raise FormatError(f"unknown type tag {tag}")


def write_file(path: str, records) -> None:
    """Write ``records`` (iterable of (id, typed_value)) to ``path``.

    The type tag is inferred from the Python value: str -> tag 1,
    int -> tag 2, bytes/bytearray -> tag 3.
    """
    payloads = []
    for rec_id, value in records:
        if isinstance(value, str):
            tag = TAG_STRING
        elif isinstance(value, int):
            tag = TAG_U32
        elif isinstance(value, (bytes, bytearray)):
            tag = TAG_BYTES
        else:
            raise FormatError(f"unsupported value type {type(value).__name__}")
        payload = _encode_payload(tag, value)
        if not 0 <= rec_id <= 0xFFFF:
            raise FormatError(f"id {rec_id} does not fit in u16")
        payloads.append(RECORD_HEAD.pack(rec_id, tag, len(payload)) + payload)

    count = len(payloads)
    if count > 0xFFFF:
        raise FormatError(f"{count} records do not fit in u16 count")
    with open(path, "wb") as fh:
        fh.write(HEADER.pack(MAGIC, VERSION, count))
        for blob in payloads:
            fh.write(blob)


def read_file(path: str):
    """Read a PKT1 file, returning a list of ``(id, typed_value)`` tuples.

    Raises BadMagic, UnsupportedVersion, TruncatedFile or FormatError.
    """
    with open(path, "rb") as fh:
        data = fh.read()

    if len(data) < HEADER.size:
        raise TruncatedFile("file shorter than PKT1 header")

    magic, version, count = HEADER.unpack_from(data, 0)
    if magic != MAGIC:
        raise BadMagic(f"bad magic {magic!r}, expected {MAGIC!r}")
    if version != VERSION:
        raise UnsupportedVersion(f"unsupported version {version}, expected {VERSION}")

    records = []
    offset = HEADER.size
    for index in range(count):
        if offset + RECORD_HEAD.size > len(data):
            raise TruncatedFile(
                f"truncated at record index {index}: missing record header"
            )
        rec_id, tag, length = RECORD_HEAD.unpack_from(data, offset)
        offset += RECORD_HEAD.size
        end = offset + length
        if end > len(data):
            have = len(data) - offset
            raise TruncatedFile(
                f"truncated at record index {index}: "
                f"payload needs {length} bytes, only {have} available"
            )
        records.append((rec_id, _decode_payload(tag, data[offset:end])))
        offset = end

    return records

